import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  FaArrowLeft,
  FaMapMarkerAlt,
  FaNavigation,
  FaCar,
  FaSearchLocation
} from 'react-icons/fa';
import './SmartTourism.css';

const talukas = [
  {
    id: 1,
    name: 'Ooty',
    fullName: 'Udagamandalam Taluk',
    places: [
      { id: 1, name: 'Ooty Lake', type: 'Lake', rating: 4.5 },
      { id: 2, name: 'Botanical Garden', type: 'Garden', rating: 4.7 },
      { id: 3, name: 'Doddabetta Peak', type: 'Viewpoint', rating: 4.6 },
      { id: 4, name: 'Rose Garden', type: 'Garden', rating: 4.4 },
      { id: 5, name: 'Pykara Lake', type: 'Lake', rating: 4.3 }
    ]
  },
  {
    id: 2,
    name: 'Coonoor',
    fullName: 'Coonoor Taluk',
    places: [
      { id: 1, name: 'Dolphin Nose', type: 'Viewpoint', rating: 4.6 },
      { id: 2, name: "Lamb's Rock", type: 'Viewpoint', rating: 4.5 },
      { id: 3, name: 'Echo Rock', type: 'Attraction', rating: 4.3 },
      { id: 4, name: 'Lakshmi Hotel', type: 'Hotel', rating: 4.2 },
      { id: 5, name: 'Ramachandra Hotel', type: 'Hotel', rating: 4.1 },
      { id: 6, name: "Modi's Cafe", type: 'Cafe', rating: 4.4 },
      { id: 7, name: 'Catherine Falls', type: 'Waterfall', rating: 4.5 },
      { id: 8, name: "Sim's Park", type: 'Park', rating: 4.3 }
    ]
  },
  {
    id: 3,
    name: 'Gudalur',
    fullName: 'Gudalur Taluk',
    places: [
      { id: 1, name: 'Needle Rock View Point', type: 'Viewpoint', rating: 4.4 },
      { id: 2, name: 'Gudalur Market', type: 'Market', rating: 4.2 },
      { id: 3, name: 'Tea Plantations', type: 'Plantation', rating: 4.5 },
      { id: 4, name: 'Frog Hill', type: 'Viewpoint', rating: 4.3 }
    ]
  },
  {
    id: 4,
    name: 'Pandalur',
    fullName: 'Pandalur Taluk',
    places: [
      { id: 1, name: 'Pandalur Temple', type: 'Temple', rating: 4.3 },
      { id: 2, name: 'Coffee Estates', type: 'Plantation', rating: 4.4 },
      { id: 3, name: 'Moyar River', type: 'River', rating: 4.2 },
      { id: 4, name: 'Devala', type: 'Town', rating: 4.1 }
    ]
  },
  {
    id: 5,
    name: 'Kotagiri',
    fullName: 'Kotagiri Taluk',
    places: [
      { id: 1, name: 'Kodand View Point', type: 'Viewpoint', rating: 4.5 },
      { id: 2, name: 'Catherine Falls', type: 'Waterfall', rating: 4.5 },
      { id: 3, name: 'Longwood Shola', type: 'Forest', rating: 4.4 },
      { id: 4, name: 'Rangaswamy Peak', type: 'Viewpoint', rating: 4.3 }
    ]
  },
  {
    id: 6,
    name: 'Kundah',
    fullName: 'Kundah Taluk',
    places: [
      { id: 1, name: 'Avalanche Lake', type: 'Lake', rating: 4.6 },
      { id: 2, name: 'Emerald Lake', type: 'Lake', rating: 4.5 },
      { id: 3, name: 'Upper Bhavani', type: 'Viewpoint', rating: 4.5 },
      { id: 4, name: 'Kundah Dam', type: 'Attraction', rating: 4.2 }
    ]
  }
];

const talukaMapRegions = [
  { id: 'pandalur', name: 'Pandalur', className: 'region-pandalur', data: talukas.find((taluka) => taluka.name === 'Pandalur') },
  { id: 'gudalur', name: 'Gudalur', className: 'region-gudalur', data: talukas.find((taluka) => taluka.name === 'Gudalur') },
  { id: 'ooty', name: 'Udagamandalam', className: 'region-ooty', data: talukas.find((taluka) => taluka.name === 'Ooty') },
  { id: 'kotagiri', name: 'Kotagiri', className: 'region-kotagiri', data: talukas.find((taluka) => taluka.name === 'Kotagiri') },
  { id: 'coonoor', name: 'Coonoor', className: 'region-coonoor', data: talukas.find((taluka) => taluka.name === 'Coonoor') },
  { id: 'kundah', name: 'Kundah', className: 'region-kundah', data: talukas.find((taluka) => taluka.name === 'Kundah') }
];

function SmartTourism() {
  const navigate = useNavigate();
  const [selectedTaluka, setSelectedTaluka] = useState(null);
  const [selectedPlace, setSelectedPlace] = useState(null);
  const [fromLocation, setFromLocation] = useState('');
  const [showNavigation, setShowNavigation] = useState(false);

  const handleBack = () => {
    if (showNavigation) {
      setShowNavigation(false);
      setSelectedPlace(null);
      setFromLocation('');
    } else if (selectedTaluka) {
      setSelectedTaluka(null);
    } else {
      navigate('/');
    }
  };

  const handleNavigation = (place) => {
    setSelectedPlace(place);
    setShowNavigation(true);
  };

  const getDistance = () => {
    const distances = {
      Coimbatore: { Ooty: '88 km', Coonoor: '75 km', Gudalur: '110 km', Pandalur: '125 km', Kotagiri: '70 km', Kundah: '105 km' },
      Chennai: { Ooty: '535 km', Coonoor: '520 km', Gudalur: '555 km', Pandalur: '570 km', Kotagiri: '510 km', Kundah: '545 km' },
      Bangalore: { Ooty: '270 km', Coonoor: '255 km', Gudalur: '295 km', Pandalur: '315 km', Kotagiri: '245 km', Kundah: '285 km' }
    };
    return distances[fromLocation]?.[selectedTaluka?.name] || 'Route distance unavailable';
  };

  const getTravelTime = () => {
    if (fromLocation === 'Coimbatore') return '2.5 - 3.5 hours';
    if (fromLocation === 'Bangalore') return '6 - 7 hours';
    if (fromLocation === 'Chennai') return '10 - 11 hours';
    return 'Travel time depends on route and traffic';
  };

  const openGoogleMaps = () => {
    if (!fromLocation || !selectedPlace || !selectedTaluka) return;
    const destination = `${selectedPlace.name}, ${selectedTaluka.name}, The Nilgiris, Tamil Nadu`;
    const url = `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(fromLocation)}&destination=${encodeURIComponent(destination)}&travelmode=driving`;
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  return (
    <div className="smart-tourism-container">
      <motion.header className="tourism-header" initial={{ y: -50 }} animate={{ y: 0 }}>
        <button className="back-btn" onClick={handleBack}>
          <FaArrowLeft /> Back
        </button>
        <h1>
          {showNavigation ? 'Navigation Guide' : selectedTaluka ? `${selectedTaluka.name} Tourism` : 'Smart Tourism'}
        </h1>
        <div className="header-spacer" />
      </motion.header>

      <main className="tourism-main">
        {!selectedTaluka && !showNavigation && (
          <motion.section className="map-section" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            <h2 className="section-title">🗺️ Explore Nilgiris Taluks</h2>
            <p className="section-subtitle">Click any taluk on the map to explore tourist places.</p>

            <div className="nilgiris-map-wrapper">
              <img src="/nilgiris-taluks-map.jpg" alt="Map of the six Nilgiris taluks" className="nilgiris-map" />
              {talukaMapRegions.map((region) => (
                <button
                  key={region.id}
                  type="button"
                  className={`map-click-region ${region.className}`}
                  onClick={() => setSelectedTaluka(region.data)}
                  title={`Explore ${region.name}`}
                  aria-label={`Explore ${region.name}`}
                >
                  <span>{region.name}</span>
                </button>
              ))}
            </div>

            <div className="map-legend">
              {talukaMapRegions.map((region) => (
                <button key={region.id} type="button" className="legend-item" onClick={() => setSelectedTaluka(region.data)}>
                  <span className="legend-dot" />
                  {region.name}
                </button>
              ))}
            </div>
          </motion.section>
        )}

        {selectedTaluka && !showNavigation && (
          <motion.section className="places-section" initial={{ opacity: 0, x: 80 }} animate={{ opacity: 1, x: 0 }}>
            <h2 className="section-title">📍 Places in {selectedTaluka.name}</h2>
            <p className="section-subtitle">Select a place to view route guidance.</p>

            <div className="places-grid">
              {selectedTaluka.places.map((place, index) => (
                <motion.button
                  key={place.id}
                  type="button"
                  className="place-card"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.06 }}
                  whileHover={{ scale: 1.03 }}
                  onClick={() => handleNavigation(place)}
                >
                  <span className="place-icon"><FaMapMarkerAlt size={24} /></span>
                  <span className="place-details">
                    <strong>{place.name}</strong>
                    <small>{place.type}</small>
                    <em>⭐ {place.rating}/5</em>
                  </span>
                  <span className="navigate-arrow">→</span>
                </motion.button>
              ))}
            </div>
          </motion.section>
        )}

        {showNavigation && selectedPlace && selectedTaluka && (
          <motion.section className="navigation-section" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}>
            <div className="navigation-card">
              <div className="nav-header">
                <FaNavigation size={38} color="#2E7D32" />
                <h2>Navigate to {selectedPlace.name}</h2>
              </div>

              <div className="location-inputs">
                <div className="location-field">
                  <label htmlFor="from-location">From location</label>
                  <select id="from-location" value={fromLocation} onChange={(event) => setFromLocation(event.target.value)} className="location-select">
                    <option value="">Select your location</option>
                    <option value="Coimbatore">Coimbatore</option>
                    <option value="Chennai">Chennai</option>
                    <option value="Bangalore">Bangalore</option>
                    <option value="Ooty">Ooty</option>
                    <option value="Coonoor">Coonoor</option>
                  </select>
                </div>

                <div className="location-field">
                  <label htmlFor="to-location">Destination</label>
                  <input id="to-location" className="location-input" readOnly value={`${selectedPlace.name}, ${selectedTaluka.name}, Nilgiris`} />
                </div>
              </div>

              {fromLocation ? (
                <div className="route-info">
                  <div className="route-card">
                    <div className="route-icon"><FaCar size={30} /></div>
                    <div className="route-details">
                      <h3>🚗 Driving route</h3>
                      <p><strong>Distance:</strong> {getDistance()}</p>
                      <p><strong>Estimated time:</strong> {getTravelTime()}</p>
                      <p className="route-note">Actual route, time, and traffic details will be shown by Google Maps.</p>
                    </div>
                  </div>

                  <div className="map-placeholder">
                    <FaSearchLocation size={55} color="#ffffff" />
                    <p>Ready for Google Maps navigation</p>
                  </div>

                  <button type="button" className="start-navigation-btn" onClick={openGoogleMaps}>
                    <FaNavigation /> Open Google Maps
                  </button>
                </div>
              ) : (
                <p className="select-note">👆 Choose your starting location to view the estimated route.</p>
              )}
            </div>
          </motion.section>
        )}
      </main>
    </div>
  );
}

export default SmartTourism;
